function pick(x:number,y:number){let nearest:Joint|null=null,best=25;for(const j of joints){const p=new THREE.Vector3(j.x,j.y,j.z).project(camera);if(p.z<-1||p.z>1)continue;const distance=Math.hypot((p.x+1)*innerWidth/2-x,(1-p.y)*innerHeight/2-y);if(distance<best){best=distance;nearest=j}}return nearest}
