$('#newProject').onclick=()=>{$('#setup').hidden=false;$('#setupError').textContent='';updateSetup()};
$('#setupCancel').onclick=()=>{$('#setup').hidden=true};
$('#setupCreate').onclick=()=>{const model=$<HTMLSelectElement>('#setupModel').value,arms=$<HTMLInputElement>('#setupArms').checked, garment=$<HTMLSelectElement>('#setupGarment').value;const figure=model==='maquette'?maquette($<HTMLSelectElement>('#setupShape').value as Silhouette,arms,$<HTMLInputElement>('#setupFingers').checked):starter(model);const items=garment==='none'?[]:garmentPreset(garment as GarmentPreset,figure.edges,.02,.02);if(items===null){$('#setupError').textContent='This garment preset needs a maquette or stick figure with both arms. Select None or add shells later.';return}checkpoint();const asymmetric=['hand','foot','ear','horn'].includes(model);$<HTMLInputElement>('#mirror').checked=!asymmetric;$<HTMLInputElement>('#brushMirror').checked=!asymmetric;joints=figure.joints;edges=figure.edges;fitted=['shirt','jacket','pants'].includes(garment)?[items]:[];shells=fitted.length?[]:items;next=Math.max(...joints.map(j=>j.id))+1;selected=joints[0].id;stage='skeleton';mode='move';sculptPositions=null;sculptIndices=null;sculptColors=null;showBody=true;$('#body').textContent='Hide body';const goal=$<HTMLSelectElement>('#setupOutput').value;$<HTMLSelectElement>('#detail').value=goal==='fast'?'.23':goal==='print'?'.12':'.17';$<HTMLSelectElement>('#sculptDetail').value=goal==='fast'?'0':'1';yaw=.25;pitch=.08;zoom=5.5;cameraTarget.set(0,0,0);setStageUI();sync();$('#setup').hidden=true;panelOpen(false)};
$('#akeleyToggle').onclick=()=>{if(stage!=='skeleton'){alert('Akeley’s Tool uses skeleton joints. Save your sculpt first, then select Edit skeleton to use it.');return}mode='gizmo';setStageUI();showJointInspector();$('#akeleySection').scrollIntoView({block:'start'});$('#hint').textContent='Akeley’s Tool: select a joint to assign a connector or export a fit test.';$('#hint').hidden=false};
$('#garmentToggle').onclick=()=>{refreshShellBones();panelOpen(true);$('#garmentSection').scrollIntoView({block:'start'})};
$('#addPreset').onclick=()=>{const pieces=garmentPreset($<HTMLSelectElement>('#garmentPreset').value as GarmentPreset,edges,Number($<HTMLInputElement>('#shellGap').value),Number($<HTMLInputElement>('#shellThickness').value));if(!pieces){$('#presetStatus').textContent='These presets require the stick figure skeleton with its original bones. Use custom shells for other creatures.';return}if(shells.length+pieces.length>30){$('#presetStatus').textContent='This would exceed the 30-shell limit. Remove shells first.';return}checkpoint();const kind=$<HTMLSelectElement>('#garmentPreset').value;if(['shirt','jacket','pants'].includes(kind)){if(fitted.length>=12){$('#presetStatus').textContent='Maximum 12 fitted garments.';return}fitted.push(pieces)}else shells.push(...pieces);dirty=true;persist();$('#presetStatus').textContent='Preset added. Fitted garments are experimental; inspect openings and fit.'};
$('#shellAdd').onclick=()=>{const [a,b]=$<HTMLSelectElement>('#shellBone').value.split(',').map(Number);if(!edges.some(e=>e[0]===a&&e[1]===b))return;if(shells.length>=30){alert('Maximum 30 shells.');return}checkpoint();shells.push({a,b,band:$<HTMLSelectElement>('#shellShape').value==='band',gap:Number($<HTMLInputElement>('#shellGap').value),thickness:Number($<HTMLInputElement>('#shellThickness').value)});dirty=true;persist()};
$('#shellClear').onclick=()=>{if(shells.length||fitted.length){checkpoint();shells=[];fitted=[];dirty=true;persist()}};
$('#shellExport').onclick=()=>{if(!shells.length&&!fitted.length){alert('Add a shell first.');return}if(fitted.length&&!bodyMesh){alert('Show body before exporting fitted garments.');return}let text='# Pocket Sculpt shell objects\n',offset=1;for(const [i,s] of shells.entries()){const a=get(s.a),b=get(s.b);if(!a||!b)continue;const g=shellGeometry(a,b,s),p=g.getAttribute('position'),ix=g.getIndex();if(!p||!ix){g.dispose();continue}text+=`o shell_${i+1}\n`;for(let k=0;k<p.count;k++)text+=`v ${p.getX(k)} ${p.getY(k)} ${p.getZ(k)}\n`;for(let k=0;k<ix.count;k+=3)text+=`f ${ix.getX(k)+offset} ${ix.getX(k+1)+offset} ${ix.getX(k+2)+offset}\n`;offset+=p.count;g.dispose()}if(bodyMesh)for(const [i,group] of fitted.entries()){const g=fittedGarment(bodyMesh.geometry,joints,edges,group),p=g.getAttribute('position'),ix=g.getIndex()!;text+=`o fitted_${i+1}\n`;for(let k=0;k<p.count;k++)text+=`v ${p.getX(k)} ${p.getY(k)} ${p.getZ(k)}\n`;for(let k=0;k<ix.count;k+=3)text+=`f ${ix.getX(k)+offset} ${ix.getX(k+1)+offset} ${ix.getX(k+2)+offset}\n`;offset+=p.count;g.dispose()}download('pocket-shells.obj',text,'text/plain')};
$('#startersToggle').onclick=()=>{panelOpen(true);$('#starterSection').scrollIntoView({block:'start'})};
$('#quickBrush').onclick=()=>{panelOpen($('#toolPanel').hidden);if(!$('#toolPanel').hidden)$('#sculptControls').scrollIntoView({block:'start'})};
$('#settingsToggle').onclick=()=>panelOpen($('#toolPanel').hidden);$('#closePanel').onclick=()=>panelOpen(false);$('#helpToggle').onclick=()=>{const hint=$('#hint');hint.hidden=!hint.hidden;$('#helpToggle').setAttribute('aria-expanded',String(!hint.hidden))};
document.querySelectorAll<HTMLButtonElement>('[data-mode]').forEach(b=>b.onclick=()=>{const repeat=stage==='sculpt'&&mode===b.dataset.mode&&mode!=='orbit';mode=b.dataset.mode!;document.querySelectorAll('[data-mode]').forEach(v=>v.classList.toggle('active',v===b));if(repeat){panelOpen(true);$('#sculptControls').scrollIntoView({block:'start'})}});
for(const [inputId,outputId] of [['brushSize','brushSizeValue'],['brushStrength','brushStrengthValue']]){$<HTMLInputElement>('#'+inputId).addEventListener('input',e=>{$('#'+outputId).textContent=(e.target as HTMLInputElement).value})}
let flattenStart='';$<HTMLInputElement>('#jointFlatten').onpointerdown=()=>flattenStart=snap();$<HTMLInputElement>('#jointFlatten').oninput=e=>{const j=get(selected);if(!j)return;j.flatten=Number((e.target as HTMLInputElement).value);j.scaleZ=j.flatten;const other=$<HTMLInputElement>('#mirror').checked?mirroredJoint(j):undefined;if(other){other.flatten=j.flatten;other.scaleZ=j.flatten;}$('#flattenValue').textContent=j.flatten.toFixed(2);dirty=true};$<HTMLInputElement>('#jointFlatten').onchange=()=>{if(flattenStart&&flattenStart!==snap())remember(flattenStart);flattenStart='';persist()};
let radiusStart='';$<HTMLInputElement>('#radius').onpointerdown=()=>radiusStart=snap();$<HTMLInputElement>('#radius').oninput=e=>{const j=get(selected);if(j){j.r=Number((e.target as HTMLInputElement).value);const other=$<HTMLInputElement>('#mirror').checked?mirroredJoint(j):undefined;if(other)other.r=j.r;$('#radiusValue').textContent=j.r.toFixed(2);dirty=true}};$<HTMLInputElement>('#radius').onchange=()=>{if(radiusStart&&radiusStart!==snap())remember(radiusStart);radiusStart='';persist()};$<HTMLSelectElement>('#detail').onchange=()=>dirty=true;$<HTMLSelectElement>('#bodySmooth').onchange=()=>dirty=true;
$('#stage').onclick=()=>{if(stage==='skeleton'){try{let g=makeBody(),applied=0;const levels=Number($<HTMLSelectElement>('#sculptDetail').value);try{for(let i=0;i<levels;i++){if(!canRefineForSculpt(g))break;const refined=refineForSculpt(g);g.dispose();g=refined;applied++}}catch(err){g.dispose();throw err}projectToBody(g,joints,edges,1);checkpoint();sculptPositions=Array.from(g.getAttribute('position').array as ArrayLike<number>);sculptIndices=Array.from(g.getIndex()!.array as ArrayLike<number>);sculptColors=[];for(let i=0;i<sculptPositions.length;i+=3)sculptColors.push(baseColor.r,baseColor.g,baseColor.b);g.dispose();stage='sculpt';mode='build';showBody=true;setStageUI();if(applied<levels){$('#hint').textContent=`Sculpting started at safe detail (${applied} of ${levels} requested subdivision levels). You can adjust detail in Settings.`;$('#hint').hidden=false}dirty=true;persist()}catch(e){alert(String(e))}}else if(confirm('Return to the skeleton? Sculpted details and paint will be discarded.')){checkpoint();stage='skeleton';mode='move';sculptPositions=null;sculptIndices=null;sculptColors=null;setStageUI();dirty=true;persist()}};
let pendingStarter:string|null=null;
document.querySelectorAll<HTMLButtonElement>('[data-starter]').forEach(button=>button.onclick=()=>{pendingStarter=button.dataset.starter!;$('#starterMessage').textContent='Start a new '+button.textContent?.trim()+' creature?';$('#starterConfirm').hidden=false;document.querySelectorAll('[data-starter]').forEach(x=>x.classList.toggle('active',x===button));$('#starterConfirm').scrollIntoView({block:'nearest'})});
$('#cancelStarter').onclick=()=>{pendingStarter=null;$('#starterConfirm').hidden=true;document.querySelectorAll('[data-starter]').forEach(x=>x.classList.remove('active'))};
$('#applyStarter').onclick=()=>{if(!pendingStarter)return;const name=pendingStarter;checkpoint();shells=[];fitted=[];stage='skeleton';mode='move';sculptPositions=null;sculptIndices=null;sculptColors=null;showBody=true;$('#body').textContent='Hide body';yaw=.25;pitch=.08;zoom=5.5;cameraTarget.set(0,0,0);setStageUI();initial(name);pendingStarter=null;$('#starterConfirm').hidden=true;document.querySelectorAll('[data-starter]').forEach(x=>x.classList.remove('active'));panelOpen(false)};
$('#subdivide').onclick=()=>{if(stage!=='sculpt'||!bodyMesh)return;try{const refined=refineForSculpt(bodyMesh.geometry);checkpoint();sculptPositions=Array.from(refined.getAttribute('position').array as ArrayLike<number>);sculptIndices=Array.from(refined.getIndex()!.array as ArrayLike<number>);sculptColors=refined.getAttribute('color')?Array.from(refined.getAttribute('color').array as ArrayLike<number>):null;refined.dispose();dirty=true;persist()}catch(e){alert(String(e))}};
$('#body').onclick=()=>{showBody=!showBody;$('#body').textContent=showBody?'Hide body':'Show body';dirty=true};$('#resetView').onclick=()=>{yaw=.25;pitch=.08;zoom=5.5;cameraTarget.set(0,0,0)};$('#reset').onclick=()=>{if(confirm('Reset creature?')){checkpoint();shells=[];fitted=[];stage='skeleton';mode='move';sculptPositions=null;sculptIndices=null;sculptColors=null;setStageUI();initial()}};$('#undo').onclick=()=>{const s=history.pop();if(s){redoHistory.push(snap());restore(s)}};$('#redo').onclick=()=>{const s=redoHistory.pop();if(s){history.push(snap());restore(s)}};
function download(name:string,content:string,type:string){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
$('#save').onclick=()=>download('pocket-creature-v061.json',snap(),'application/json');
$('#obj').onclick=()=>{try{const g=stage==='sculpt'&&bodyMesh?bodyMesh.geometry.clone():makeBody(),p=g.getAttribute('position'),ix=g.getIndex(),colors=g.getAttribute('color');let s='# Pocket Sculpt unified surface; optional vertex RGB follows XYZ\n';for(let i=0;i<p.count;i++){let rgb='';if(colors){const c=new THREE.Color().setRGB(colors.getX(i),colors.getY(i),colors.getZ(i)).convertLinearToSRGB();rgb=` ${c.r} ${c.g} ${c.b}`}s+=`v ${p.getX(i)} ${p.getY(i)} ${p.getZ(i)}${rgb}\n`;}if(ix)for(let i=0;i<ix.count;i+=3)s+=`f ${ix.getX(i)+1} ${ix.getX(i+1)+1} ${ix.getX(i+2)+1}\n`;g.dispose();download('pocket-creature-v061.obj',s,'text/plain')}catch(e){alert(String(e))}};
$('#open').onclick=()=>$<HTMLInputElement>('#file').click();$<HTMLInputElement>('#file').onchange=async e=>{const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const content=await f.text(),previous=snap();restore(content);remember(previous)}catch(err){alert(String(err))}(e.target as HTMLInputElement).value=''};
window.addEventListener('resize',resize);resize();
async function start(){let restored=false,invalid=false;try{const saved=await loadAutosave();if(saved){try{restore(saved);restored=true}catch(e){invalid=true;console.warn('Could not restore saved creature:',e)}}}catch(e){console.warn('Could not read saved creature:',e)}if(!restored){if(!invalid){$('#setup').hidden=false;updateSetup()}autosavePaused=invalid;setStageUI();initial();autosavePaused=false;if(invalid){$('#saveStatus').textContent='Previous autosave could not be opened. Open a saved project backup.';$('#saveStatus').hidden=false}}animate()}
$<HTMLInputElement>('#showLabels').onchange=()=>updateJointLabels();
function updateJointLabels(){const active=stage==='skeleton'&&$<HTMLInputElement>('#showLabels').checked;$('#jointLabels').hidden=!active;if(!active)return;document.querySelectorAll<HTMLElement>('#jointLabels span').forEach(el=>{const j=get(Number(el.dataset.joint));if(!j){el.hidden=true;return}const p=new THREE.Vector3(j.x,j.y,j.z).project(camera);el.hidden=p.z< -1||p.z>1;el.style.left=((p.x+1)*innerWidth/2+10)+'px';el.style.top=((1-p.y)*innerHeight/2-8)+'px'})}
let lastPreview=0;function animate(t=0){requestAnimationFrame(animate);updateCamera();if(dirty&&pointers.size===0)rebuild();else if(dirty&&stage==='skeleton'&&drag?.kind==='joint'&&t-lastPreview>200){rebuild(true);dirty=true;lastPreview=t}updateJointLabels();renderer.render(scene,camera)}start();
